using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using UnityEngine;
namespace HabitatShift.Core {
[Serializable] public class CatalogDto { public string schema,catalogRevision,rulesetVersion,rulesetFingerprint,canonicalLevelsFingerprint; public int levelCount; public LevelDto[] levels; }
[Serializable] public class RulesetDto { public string rulesetVersion; public float dragSweepStep,collectionTolerance,foreignSproutlingCollisionRadius,narrowCorridorDragCollisionInset,activeDragHabitatCollisionSkin,strictProjectionRadius,contactReleaseHysteresis,strictCorrectionPerSweep; public int contactSolverIterations; }
[Serializable] public class LevelDto { public int id,cols,rows; public string title,profile,challenge,difficulty; public HabitatDto[] habitats; public TargetDto[] targets; public ElevatorDto[] elevators; public IntPair[] obstacles,playableMask; }
[Serializable] public class HabitatDto { public string id,color,movementConstraint; public IntPair anchor; public IntPair[] shape; public int need; }
[Serializable] public class TargetDto { public string id,color; public FloatPair position; }
[Serializable] public class ElevatorDto { public string id,direction; public FloatPair entry; public QueueItemDto[] queue; public int nextIndex; public bool mandatory; }
[Serializable] public class QueueItemDto { public string id,color; } [Serializable] public class IntPair { public int x,y; } [Serializable] public class FloatPair { public float x,y; }
public static class CatalogLoader { const string CH="d7c920d0130ee0d54860f71247e8a7cd2b8e9c1968337ca6382f168461108270", RH="3e0a9ef1d6b3f0fde22c5814198946ba53744973d851fcf7e2cc8035e0e4ef95"; public static CatalogDto Load(out RulesetDto r) { var d=Path.Combine(Application.streamingAssetsPath,"HabitatShift");var cp=Path.Combine(d,"approved_levels_v4.json");var rp=Path.Combine(d,"ruleset_manifest_v1.json");if(!File.Exists(cp)||!File.Exists(rp)||Hash(cp)!=CH||Hash(rp)!=RH)throw new InvalidOperationException("Habitat Shift catalog missing or hash mismatch.");var raw=Regex.Replace(File.ReadAllText(cp), "\\[\\s*(-?\\d+(?:\\.\\d+)?)\\s*,\\s*(-?\\d+(?:\\.\\d+)?)\\s*\\]", "{\"x\":$1,\"y\":$2}");var c=JsonUtility.FromJson<CatalogDto>(raw);r=JsonUtility.FromJson<RulesetDto>(File.ReadAllText(rp));Validate(c,r);return c;} static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();} public static void Validate(CatalogDto c,RulesetDto r){if(c==null||c.schema!="habitat-shift-levels-v4"||c.catalogRevision!="m6-20260916-c-full-footprint-fix"||c.rulesetVersion!="continuous-core-v2"||c.levelCount!=18||c.levels==null||c.levels.Length!=18)throw new InvalidOperationException("Invalid Habitat Shift catalog identity.");if(r==null||r.rulesetVersion!="continuous-core-v2"||!Mathf.Approximately(r.dragSweepStep,.08f)||r.contactSolverIterations!=4)throw new InvalidOperationException("Invalid continuous ruleset.");for(int i=0;i<18;i++){var l=c.levels[i];if(l==null||l.id!=i+1||l.habitats==null||l.targets==null||l.elevators==null)throw new InvalidOperationException("Invalid level "+(i+1));foreach(var h in l.habitats){if(h.need<1||h.shape==null||h.shape.Length==0)throw new InvalidOperationException("Invalid habitat L"+l.id);}}} }
public enum AssistKind { NestBloom,GardenShift,RootTrim } public enum PresentationKind { DragStart,BlockedContact,Collection,ElevatorRelease,HabitatComplete,AssistSuccess,Undo,Win }
[Serializable] public class HabitatRuntime { public string id,color,constraint;public Vector2 anchor;public List<Vector2Int> shape;public int remaining;public HabitatRuntime Clone(){return new HabitatRuntime{id=id,color=color,constraint=constraint,anchor=anchor,shape=new List<Vector2Int>(shape),remaining=remaining};}}
[Serializable] public class SproutRuntime {public string id,color;public Vector2 position;public SproutRuntime Clone(){return new SproutRuntime{id=id,color=color,position=position};}}
[Serializable] public class ElevatorRuntime {public string id,direction;public Vector2 entry;public List<QueueItemDto> queue;public int nextIndex;public bool mandatory;public ElevatorRuntime Clone(){return new ElevatorRuntime{id=id,direction=direction,entry=entry,queue=new List<QueueItemDto>(queue),nextIndex=nextIndex,mandatory=mandatory};}}
[Serializable] public class RuntimeState {public int levelId,moves;public bool won;public List<HabitatRuntime> habitats=new List<HabitatRuntime>();public List<SproutRuntime> sprouts=new List<SproutRuntime>();public List<ElevatorRuntime> elevators=new List<ElevatorRuntime>();public RuntimeState Clone(){return new RuntimeState{levelId=levelId,moves=moves,won=won,habitats=habitats.Select(x=>x.Clone()).ToList(),sprouts=sprouts.Select(x=>x.Clone()).ToList(),elevators=elevators.Select(x=>x.Clone()).ToList()};}}
public class PresentationEvent {public string id,subject;public PresentationKind kind;public Vector2 position;}
public class ContinuousSession { readonly LevelDto l;readonly RulesetDto r;readonly Stack<RuntimeState> history=new Stack<RuntimeState>();int eventNo;public RuntimeState Committed{get;private set;}public RuntimeState Preview{get;private set;}public string DragId{get;private set;}public Vector2 GrabOffset{get;private set;}public List<PresentationEvent> Events=new List<PresentationEvent>(); public bool IsDragging { get { return Preview != null; } } public ContinuousSession(LevelDto level,RulesetDto rules,RuntimeState restore=null){l=level;r=rules;Committed=restore??Initial(level);} public static RuntimeState Initial(LevelDto l){return new RuntimeState{levelId=l.id,habitats=l.habitats.Select(h=>new HabitatRuntime{id=h.id,color=h.color,constraint=h.movementConstraint,anchor=new Vector2(h.anchor.x,h.anchor.y),shape=h.shape.Select(q=>new Vector2Int(q.x,q.y)).ToList(),remaining=h.need}).ToList(),sprouts=l.targets.Select(t=>new SproutRuntime{id=t.id,color=t.color,position=new Vector2(t.position.x,t.position.y)}).ToList(),elevators=l.elevators.Select(e=>new ElevatorRuntime{id=e.id,direction=e.direction,entry=new Vector2(e.entry.x,e.entry.y),queue=e.queue.ToList(),nextIndex=e.nextIndex,mandatory=e.mandatory}).ToList()};}
public bool BeginDrag(string id,Vector2 p){var h=Committed.habitats.FirstOrDefault(x=>x.id==id);if(h==null)return false;Preview=Committed.Clone();DragId=id;GrabOffset=p-h.anchor;Emit(PresentationKind.DragStart,id,h.anchor);return true;} public void MovePointer(Vector2 p){if(Preview==null)return;var h=Preview.habitats.FirstOrDefault(x=>x.id==DragId);if(h==null)return;var d=p-GrabOffset-h.anchor;if(h.constraint=="HORIZONTAL_ONLY")d.y=0;if(h.constraint=="VERTICAL_ONLY")d.x=0;int n=Mathf.Max(1,Mathf.CeilToInt(d.magnitude/r.dragSweepStep));for(int i=0;i<n;i++){var a=h.anchor+d/n;if(!Legal(Preview,h,a)){Emit(PresentationKind.BlockedContact,h.id,h.anchor);break;}h.anchor=a;Collect(Preview,h);if(!Preview.habitats.Contains(h))break;}} public bool EndDrag(bool cancel=false){if(Preview==null)return false;if(cancel){Preview=null;return false;}var h=Preview.habitats.FirstOrDefault(x=>x.id==DragId);if(h!=null)h.anchor=Settle(Preview,h);bool changed=Sig(Committed)!=Sig(Preview);if(changed){history.Push(Committed.Clone());Committed=Preview;Committed.moves++;Feed();Win();}Preview=null;DragId=null;return changed;} public bool Undo(){if(history.Count==0)return false;Committed=history.Pop();Emit(PresentationKind.Undo,"",Vector2.zero);return true;}public void Restart(){history.Clear();Committed=Initial(l);Events.Clear();}
public bool UseAssist(AssistKind k,string hid,string sid,Vector2Int leaf){var h=Committed.habitats.FirstOrDefault(x=>x.id==hid);var s=Committed.sprouts.FirstOrDefault(x=>x.id==sid);bool ok=false;if(k==AssistKind.NestBloom&&h!=null&&s!=null&&h.color==s.color&&h.remaining>0&&Dist(h,s.position)<=1.5f){Capture(Committed,h,s);ok=true;}if(k==AssistKind.GardenShift&&h!=null&&s!=null&&h.color==s.color&&h.remaining>0){Capture(Committed,h,s);ok=true;}if(k==AssistKind.RootTrim&&h!=null&&h.shape.Count>1&&h.shape.Contains(leaf)){h.shape.Remove(leaf);ok=Connected(h.shape)&&Legal(Committed,h,h.anchor);if(!ok)h.shape.Add(leaf);}if(ok){Win();Emit(PresentationKind.AssistSuccess,hid,h==null?Vector2.zero:h.anchor);}return ok;}
void Collect(RuntimeState s,HabitatRuntime h){foreach(var x in s.sprouts.Where(x=>x.color==h.color&&h.remaining>0&&Contains(h,x.position,r.collectionTolerance)).ToArray())Capture(s,h,x);}void Capture(RuntimeState s,HabitatRuntime h,SproutRuntime x){s.sprouts.Remove(x);h.remaining--;Emit(PresentationKind.Collection,x.id,x.position);if(h.remaining==0){s.habitats.Remove(h);Emit(PresentationKind.HabitatComplete,h.id,h.anchor);}}void Feed(){foreach(var e in Committed.elevators){if(e.nextIndex>=e.queue.Count||Committed.sprouts.Any(x=>(x.position-e.entry).sqrMagnitude<.0001f)||Committed.habitats.Any(x=>Contains(x,e.entry,0)))continue;var q=e.queue[e.nextIndex++];Committed.sprouts.Add(new SproutRuntime{id=q.id,color=q.color,position=e.entry});Emit(PresentationKind.ElevatorRelease,e.id,e.entry);}}void Win(){Committed.won=Committed.habitats.Count==0&&Committed.sprouts.Count==0&&Committed.elevators.All(x=>!x.mandatory||x.nextIndex>=x.queue.Count);if(Committed.won)Emit(PresentationKind.Win,"",Vector2.zero);}Vector2 Settle(RuntimeState s,HabitatRuntime h){var b=new Vector2(Mathf.Round(h.anchor.x),Mathf.Round(h.anchor.y));for(int z=0;z<8;z++)for(int y=-z;y<=z;y++)for(int x=-z;x<=z;x++){var p=b+new Vector2(x,y);if(Legal(s,h,p))return p;}return h.anchor;}bool Legal(RuntimeState s,HabitatRuntime h,Vector2 a){foreach(var c in h.shape){var p=a+c;int x0=Mathf.FloorToInt(p.x+.0001f),x1=Mathf.CeilToInt(p.x+1-.0001f),y0=Mathf.FloorToInt(p.y+.0001f),y1=Mathf.CeilToInt(p.y+1-.0001f);for(int y=y0;y<y1;y++)for(int x=x0;x<x1;x++)if(!Playable(x,y)||(l.obstacles??new IntPair[0]).Any(o=>o.x==x&&o.y==y))return false;}foreach(var o in s.habitats.Where(x=>x!=h))if(Overlap(h,a,o,o.anchor,r.activeDragHabitatCollisionSkin))return false;foreach(var x in s.sprouts.Where(x=>x.color!=h.color))if(Dist(h,x.position,a)<r.foreignSproutlingCollisionRadius)return false;return true;}bool Playable(int x,int y){return x>=0&&y>=0&&x<l.cols&&y<l.rows&&(l.playableMask==null||l.playableMask.Length==0||l.playableMask.Any(c=>c.x==x&&c.y==y));}static bool Contains(HabitatRuntime h,Vector2 p,float pad,Vector2? a=null){var q=a??h.anchor;return h.shape.Any(c=>p.x>=q.x+c.x-pad&&p.x<=q.x+c.x+1+pad&&p.y>=q.y+c.y-pad&&p.y<=q.y+c.y+1+pad);}static float Dist(HabitatRuntime h,Vector2 p,Vector2? a=null){var q=a??h.anchor;float d=float.MaxValue;foreach(var c in h.shape){var z=new Vector2(Mathf.Clamp(p.x,q.x+c.x,q.x+c.x+1),Mathf.Clamp(p.y,q.y+c.y,q.y+c.y+1));d=Mathf.Min(d,Vector2.Distance(p,z));}return d;}static bool Overlap(HabitatRuntime a,Vector2 aa,HabitatRuntime b,Vector2 bb,float skin){foreach(var x in a.shape)foreach(var y in b.shape){var min=aa+x+Vector2.one*skin;var max=aa+x+Vector2.one*(1-skin);var omin=bb+y;var omax=bb+y+Vector2.one;if(min.x<omax.x&&max.x>omin.x&&min.y<omax.y&&max.y>omin.y)return true;}return false;}static bool Connected(List<Vector2Int> c){var seen=new HashSet<Vector2Int>{c[0]};var q=new Queue<Vector2Int>();q.Enqueue(c[0]);while(q.Count>0){var p=q.Dequeue();foreach(var n in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right})if(c.Contains(p+n)&&seen.Add(p+n))q.Enqueue(p+n);}return seen.Count==c.Count;}void Emit(PresentationKind k,string s,Vector2 p){Events.Add(new PresentationEvent{id=Committed.levelId+"-"+(++eventNo),kind=k,subject=s,position=p});}static string Sig(RuntimeState s){return string.Join("|",s.habitats.Select(h=>h.id+":"+h.anchor+":"+h.remaining+":"+h.shape.Count))+";"+string.Join("|",s.sprouts.Select(x=>x.id+":"+x.position))+";"+string.Join("|",s.elevators.Select(x=>x.id+":"+x.nextIndex));}}
}



